function r(t){const e=t/100;return new Intl.NumberFormat("ar-MA",{maximumFractionDigits:0}).format(e)+" درهم"}function a(t){try{return new Intl.DateTimeFormat("ar-MA",{dateStyle:"medium",timeStyle:"short"}).format(new Date(t))}catch{return t}}function n(t){if(!t)return"—";try{return new Intl.DateTimeFormat("ar-MA",{dateStyle:"medium"}).format(new Date(t))}catch{return t}}function m(t){const e=t.replace(/\D/g,"");return e.startsWith("0")?"212"+e.slice(1):e}export{a,n as b,r as f,m as t};
